import java.time.Duration;
import java.util.*;
import java.util.function.*;

import io.github.resilience4j.circuitbreaker.*;

public class Main {
    public static void main(String[] args) {
        CircuitBreaker cb = CircuitBreaker.ofDefaults("pembayaran");
        System.out.println("Awal: " + cb.getState());
        cb.transitionToOpenState();
        System.out.println("Setelah dibuka: " + cb.getState());
        try {
            cb.executeSupplier(() -> "bayar");
        } catch (CallNotPermittedException e) {
            System.out.println("Ditolak tanpa memanggil layanan");
        }
        cb.transitionToHalfOpenState();
        System.out.println("Uji coba: " + cb.executeSupplier(() -> "bayar") + ", sirkuit " + cb.getState());
    }
}

