import java.time.Duration;
import java.util.*;
import java.util.function.*;

import io.github.resilience4j.circuitbreaker.*;

public class Main {
    public static void main(String[] args) {
        GudangPalsu gudang = new GudangPalsu("timeout", "timeout", "ok", "timeout");
        CircuitBreakerConfig config = CircuitBreakerConfig.custom()
                .slidingWindowSize(4)
                .minimumNumberOfCalls(4)
                .failureRateThreshold(50)
                .waitDurationInOpenState(Duration.ofMillis(300))
                .permittedNumberOfCallsInHalfOpenState(1)
                .build();
        CircuitBreaker cb = CircuitBreaker.of("gudang", config);
        Supplier<Integer> cek = CircuitBreaker.decorateSupplier(cb, () -> gudang.cekStok("kopi"));
        for (int i = 1; i <= 6; i++) {
            try {
                System.out.println(i + ". stok " + cek.get());
            } catch (CallNotPermittedException e) {
                System.out.println(i + ". ditolak, sirkuit " + cb.getState());
            } catch (IllegalStateException e) {
                System.out.println(i + ". gagal: " + e.getMessage());
            }
        }
        System.out.println("Panggilan ke gudang: " + gudang.panggilan);
    }
}

class GudangPalsu {
    private final Deque<String> jadwal;
    int panggilan;

    GudangPalsu(String... jadwal) {
        this.jadwal = new ArrayDeque<>(Arrays.asList(jadwal));
    }

    int cekStok(String barang) {
        panggilan++;
        String hasil = jadwal.isEmpty() ? "ok" : jadwal.poll();
        if (hasil.equals("timeout")) {
            throw new IllegalStateException("timeout ke gudang");
        }
        if (hasil.equals("400")) {
            throw new IllegalArgumentException("barang tidak dikenal: " + barang);
        }
        return 7;
    }
}

